const ink = Color(0xFF12233F), teal = Color(0xFF087E8B), paper = Color(0xFFF4F7FB);
final money = NumberFormat('#,##0.##', 'en_US');
String dateText(String s) { try { return DateFormat('yyyy/MM/dd').format(DateTime.parse(s)); } catch (_) { return s; } }
void main() async { WidgetsFlutterBinding.ensureInitialized(); await AppDb.instance.init(); runApp(const TahseelApp()); }

class AppDb {
  AppDb._(); static final instance = AppDb._(); Database? _db;
  Future<void> init() async { final root = await getDatabasesPath(); _db = await openDatabase(p.join(root,'tahseel.db'), version: 1, onCreate: (db, v) async {
    await db.execute('CREATE TABLE customers(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT "", note TEXT NOT NULL DEFAULT "", created_at TEXT NOT NULL)');
    await db.execute('CREATE TABLE debts(id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL, title TEXT NOT NULL, amount REAL NOT NULL, due_date TEXT NOT NULL, note TEXT NOT NULL DEFAULT "", created_at TEXT NOT NULL, FOREIGN KEY(customer_id) REFERENCES customers(id))');
    await db.execute('CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT, debt_id INTEGER NOT NULL, amount REAL NOT NULL, paid_at TEXT NOT NULL, note TEXT NOT NULL DEFAULT "", FOREIGN KEY(debt_id) REFERENCES debts(id))');
    await db.execute('CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL)');
  }, onConfigure: (db) async { await db.execute('PRAGMA foreign_keys = ON'); }); }
  Database get db => _db!;
  Future<List<Map<String,Object?>>> customers() => db.rawQuery('SELECT c.*, COALESCE((SELECT SUM(d.amount) FROM debts d WHERE d.customer_id=c.id),0) total, COALESCE((SELECT SUM(p.amount) FROM payments p JOIN debts d ON d.id=p.debt_id WHERE d.customer_id=c.id),0) paid FROM customers c ORDER BY c.name COLLATE NOCASE');
  Future<List<Map<String,Object?>>> debts() => db.rawQuery('SELECT d.*, c.name customer_name,c.phone, COALESCE((SELECT SUM(amount) FROM payments p WHERE p.debt_id=d.id),0) paid FROM debts d JOIN customers c ON c.id=d.customer_id ORDER BY d.due_date');
  Future<List<Map<String,Object?>>> payments() => db.rawQuery('SELECT p.*,d.title debt_title,c.name customer_name FROM payments p JOIN debts d ON d.id=p.debt_id JOIN customers c ON c.id=d.customer_id ORDER BY p.paid_at DESC,p.id DESC');
  Future<double> sum(String sql) async { final r=await db.rawQuery(sql); return ((r.first.values.first as num?)??0).toDouble(); }
  Future<Map<String,double>> totals() async { final debt=await sum('SELECT COALESCE(SUM(amount),0) FROM debts'); final paid=await sum('SELECT COALESCE(SUM(amount),0) FROM payments'); final cs=await db.rawQuery('SELECT COUNT(*) n FROM customers'); return {'debt':debt,'paid':paid,'remaining':(debt-paid).clamp(0,double.infinity),'customers':((cs.first['n'] as num?)??0).toDouble()}; }
  Future<void> addCustomer(String n,String phone,String note) => db.insert('customers',{'name':n.trim(),'phone':phone.trim(),'note':note.trim(),'created_at':DateTime.now().toIso8601String()}).then((_){});
  Future<void> updateCustomer(int id,String n,String phone,String note) => db.update('customers',{'name':n.trim(),'phone':phone.trim(),'note':note.trim()},where:'id=?',whereArgs:[id]).then((_){});
  Future<void> addDebt(int cid,String title,double amount,String due,String note) => db.insert('debts',{'customer_id':cid,'title':title.trim(),'amount':amount,'due_date':due,'note':note.trim(),'created_at':DateTime.now().toIso8601String()}).then((_){});
  Future<void> updateDebt(int id,int cid,String title,double amount,String due,String note) => db.update('debts',{'customer_id':cid,'title':title.trim(),'amount':amount,'due_date':due,'note':note.trim()},where:'id=?',whereArgs:[id]).then((_){});
  Future<void> addPayment(int did,double amount,String note) => db.insert('payments',{'debt_id':did,'amount':amount,'paid_at':DateTime.now().toIso8601String(),'note':note.trim()}).then((_){});
  Future<void> deleteCustomer(int id) async { await db.transaction((t) async { final ds=await t.query('debts',columns:['id'],where:'customer_id=?',whereArgs:[id]); for(final d in ds){await t.delete('payments',where:'debt_id=?',whereArgs:[d['id']]);} await t.delete('debts',where:'customer_id=?',whereArgs:[id]); await t.delete('customers',where:'id=?',whereArgs:[id]); }); }
  Future<void> deleteDebt(int id) async { await db.transaction((t) async { await t.delete('payments',where:'debt_id=?',whereArgs:[id]); await t.delete('debts',where:'id=?',whereArgs:[id]); }); }
  Future<void> deletePayment(int id) => db.delete('payments',where:'id=?',whereArgs:[id]).then((_){});
  Future<void> backup() async { final data=<String,dynamic>{}; for(final table in ['customers','debts','payments','settings']) { data[table]=await db.query(table); } data['exported_at']=DateTime.now().toIso8601String(); final dir=await getTemporaryDirectory(); final f=File(p.join(dir,'tahseel-backup-${DateTime.now().millisecondsSinceEpoch}.json')); await f.writeAsString(const JsonEncoder.withIndent('  ').convert(data)); await Share.shareXFiles([XFile(f.path)],text:'نسخة احتياطية من تحصيل'); }
}

