EdgeInsets.only(top:8),child:Text(error!,style:const TextStyle(color:Colors.red))),const SizedBox(height:14),SizedBox(width:double.infinity,child:FilledButton(onPressed:_go,child:Text(setup?'حفظ PIN والدخول':'دخول',style:const TextStyle(fontWeight:FontWeight.bold)))),const SizedBox(height:14),const Text('بياناتك محفوظة محلياً على هذا الجهاز',style:TextStyle(color:Colors.blueGrey,fontSize:12))]))))); }

